/* Field segments and goal segments are stored from the thrower's point of view. */
const originalBind=bind;
const fieldSegments=[
 ['Linksaußen','25,984 68,718 307,500 451,366 339,240 106,240','150,440','LA'],
 ['Rückraum links','25,984 68,718 307,500 553,604 438,861','300,730','RL'],
 ['Rückraum Mitte','438,861 553,604 983,604 1098,861 768,847','768,750','RM'],
 ['Kreis links','307,500 451,366 622,445 553,604','470,492','KL'],
 ['Kreis Mitte','622,445 914,445 983,604 553,604','768,565','KM'],
 ['Rückraum rechts','1511,984 1468,718 1229,500 983,604 1098,861','1236,730','RR'],
 ['7 Meter','710,470 826,470 826,532 710,532','768,503','7m'],
 ['Kreis rechts','1229,500 1085,366 914,445 983,604','1066,492','KR'],
 ['Rechtsaußen','1511,984 1468,718 1229,500 1085,366 1197,240 1430,240','1386,440','RA']
];
liveView=function(g){
 if(!g)return `<div class="topline"><div><div class="eyebrow">Bereit für den Anpfiff</div><h1>Jeder Wurf erzählt etwas.</h1><p class="muted">Erfasse dein Spiel. Entdecke die Muster.</p></div><button class="primary" data-action="newGame">＋ Neues Spiel</button></div><div class="card empty"><h2>Deine Analyse beginnt hier</h2><p>Lege zuerst zwei Mannschaften und ein Spiel an.</p><button data-action="newTeam">Mannschaft anlegen</button>${db.games.length?'<button data-tab="games">Spiele öffnen</button>':''}</div>`;
 const goals=id=>g.shots.filter(s=>s.team===id&&s.result==='Tor').length,eventEdit=(g.events||[]).some(e=>e.id===editId),legacyEdit=editId&&legacyResults.includes(draft.result)&&!results.includes(draft.result),ready=Boolean(draft.player&&draft.origin&&draft.zone!=null&&(results.includes(draft.result)||legacyEdit));
 return `<section class="match-workspace" aria-label="Spielerfassung"><div class="match-bar"><button data-tab="games" class="back-button">‹ Spiele</button><div class="match-teams"><span>${esc(teamName(g.home))}</span><strong>${goals(g.home)} : ${goals(g.away)}</strong><span>${esc(teamName(g.away))}</span></div><div class="match-timer"><input id="clock" class="clock-input" aria-label="Spielzeit Minuten und Sekunden" value="${time(elapsed)}" inputmode="numeric"><button data-action="clock" class="${running?'':'primary'}">${running?'Ⅱ Pause':'▶ Start'}</button><button data-action="period">${g.period||1}. HZ ⇄</button></div><button data-tab="analysis" class="analysis-shortcut">Auswertung ↗</button></div><div class="match-instructions"><span>${editId?'Eintrag korrigieren':'Live-Erfassung'}${g.finished?' · Spiel abgeschlossen':''}</span><span class="${draft.player?'done':''}">1 Spieler</span><span class="${draft.origin?'done':''}">2 Feldsegment</span><span class="${draft.zone!=null?'done':''}">3 Torsegment</span><span class="${draft.result?'done':''}">4 Ergebnis & speichern</span></div><div class="match-grid"><aside class="roster-panel"><div class="team-switch">${[g.home,g.away].map(id=>`<button data-team="${id}" class="${selectedTeam===id?'active':''}">${esc(teamName(id))}</button>`).join('')}</div><div class="roster-heading">Spieler wählen</div><div class="match-players">${(team(selectedTeam)?.players||[]).map(p=>`<button data-player="${p.number}" class="${draft.player===p.number?'active':''}" title="${esc(p.name)}${playerFlags(p)}"><b>${p.number}</b><small>${esc(p.name||'Spieler')}</small><small class="player-flags">${p.leftHanded?'LH ':''}${p.isKeeper?'TW':''}</small></button>`).join('')}<button data-player="?" class="${draft.player==='?'?'active':''}"><b>?</b><small>Unbekannt</small></button></div><button class="roster-edit" data-editteam="${selectedTeam}">Kader bearbeiten</button></aside><div class="field-column"><div class="field-space"><div class="drawing-field"><img src="/handballfeld.jpg" alt="Handballfeld mit neun Feldsegmenten und neun Torsegmenten" draggable="false"><svg id="field-segments" viewBox="0 0 1536 1024" role="group" aria-label="Feldsegment auswählen">${fieldSegments.map(([name,points,center,label])=>`<g role="button" tabindex="${draft.player&&!eventEdit?'0':'-1'}" aria-label="${name}" aria-pressed="${draft.origin===name}" aria-disabled="${!draft.player||eventEdit}" data-field="${name}" class="field-segment ${draft.origin===name?'selected':''}"><polygon points="${points}"/><text x="${center.split(',')[0]}" y="${center.split(',')[1]}" text-anchor="middle" dominant-baseline="central">${draft.origin===name?'✓ ':''}${label}</text></g>`).join('')}</svg><div class="goal-overlay" aria-label="Torsegment auswählen">${zones.map((z,i)=>`<button data-target="${i}" aria-label="${z}" ${!draft.player||!draft.origin||eventEdit?'disabled':''} class="${draft.zone===i?'selected':''}"><span>${draft.zone===i?'✓':i+1}</span></button>`).join('')}</div></div></div><div class="field-tools"><span>${draft.origin?esc(draft.origin)+(draft.zone!=null?' → '+zones[draft.zone]:' · Jetzt Torsegment antippen'):'Feldsegment antippen · Aus Sicht des Werfers'}</span><button data-action="resetDraft">↶ Zurücksetzen</button></div><p class="segment-help">${!draft.player?'← Zuerst Spieler auswählen':eventEdit?'Ereignis rechts auswählen, um die Korrektur zu speichern.':'Feld → Tor → Ergebnis. Technischer Fehler und Ballverlust benötigen keinen Wurf.'}</p></div><aside class="outcome-panel"><div><div class="eyebrow">${editId?'Korrektur':'Aktueller Angriff'}</div><h2>${draft.player?'#'+esc(draft.player):'Spieler wählen'}</h2><p class="muted">${esc(draft.player?playerName(selectedTeam,draft.player)||teamName(selectedTeam):'Dann Feld- und Torsegment')}</p></div><div class="outcome-buttons">${results.map(r=>`<button data-result="${r}" ${eventEdit?'disabled':''} class="${draft.result===r?'active':''}">${r==='Tor'?'● ':''}${r}</button>`).join('')}${legacyEdit?`<p class="muted">Bisher: ${esc(draft.result)}</p>`:''}</div><div class="turnover-buttons"><span class="eyebrow">Ohne Wurf · direkt speichern</span>${turnoverResults.map(r=>`<button data-turnover="${r}" ${editId&&!eventEdit?'disabled':''}>${r}</button>`).join('')}</div><div class="match-save"><button class="primary" data-action="saveShot" ${!ready||eventEdit?'disabled':''}>${editId?'Änderung speichern':'✓ Wurf speichern'}</button><button data-action="resetDraft">Verwerfen</button></div><button class="history-button" id="shot-history">Spielverlauf <span>${g.shots.length+(g.events?.length||0)}</span></button><button class="finish-button" data-action="finish">${g.finished?'Spiel wieder öffnen':'Spiel abschließen'}</button></aside></div><div class="match-footnote"><span>Lokal gespeichert · Nach dem Spiel Sicherung exportieren</span><span>Stift, Finger oder Maus · ${esc(g.date)}</span></div></section>`
};
bind=function(){
 originalBind();document.body.classList.toggle('in-match',tab==='live'&&Boolean(game()));
 if(tab!=='live'||!game())return;
 document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{if(selectedTeam!==b.dataset.team){selectedTeam=b.dataset.team;draft={};editId=null;render()}});
 document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{if(draft.player!==b.dataset.player){draft.player=b.dataset.player;render()}});
 document.querySelectorAll('[data-field]').forEach(b=>{const choose=()=>{if(!draft.player||b.getAttribute('aria-disabled')==='true')return;draft.origin=b.dataset.field;draft.throwTime??=time(elapsed);render()};b.onclick=choose;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}}});
 document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{if(draft.player&&draft.origin){draft.zone=Number(b.dataset.target);render()}});
 document.querySelectorAll('[data-turnover]').forEach(b=>b.onclick=()=>saveTurnover(b.dataset.turnover));
 $('#shot-history').onclick=()=>{const g=game(),entries=[...g.shots,...(g.events||[])].sort((a,b)=>{const seconds=t=>t.split(':').reduce((m,n)=>m*60+Number(n),0);return seconds(b.time)-seconds(a.time)});modal(`<div class="card-head"><h2>Spielverlauf (${entries.length})</h2><button data-close>Schließen</button></div><div>${entries.map(s=>`<button class="history-entry" data-history="${s.id}"><b>${esc(s.time)} · #${esc(s.player)} · ${esc(s.result)}</b><small>${esc(teamName(s.team))}${turnoverResults.includes(s.result)?' · Ohne Wurf':' · '+esc(s.origin||'Position offen')+' · '+(s.zone==null?'Ziel offen':zones[s.zone])}</small></button>`).join('')||'<p class="muted">Noch keine Einträge.</p>'}</div>`);document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const s=entries.find(s=>s.id===b.dataset.history),isEvent=turnoverResults.includes(s.result);modal(`<h2>${isEvent?'Ereignis':'Wurf'} · ${esc(s.time)} · #${esc(s.player)}</h2><p style="margin:16px 0">${esc(s.result)}</p><div class="dialog-actions"><button data-close>Schließen</button><button class="danger" id="delete-history">Löschen</button><button class="primary" id="correct-history">Korrigieren</button></div>`);$('#correct-history').onclick=()=>{editId=s.id;selectedTeam=s.team;draft={...s};$('#dialog').close();render()};$('#delete-history').onclick=()=>{if(confirm('Diesen Eintrag löschen?')){if(isEvent)g.events=g.events.filter(x=>x.id!==s.id);else g.shots=g.shots.filter(x=>x.id!==s.id);persist();$('#dialog').close();render()}}})}
};
actions.saveShot=()=>saveShot();
render();
